START TRANSACTION;
INSERT INTO `alrowad_uni_rust`.`permissions` (`permission_code`,`permission_name`,`description`,`module_id`,`is_active`,`created_at`,`updated_at`) SELECT x.code,x.name,'owned:supplementary-exam-grading-phase5',m.module_id,1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM (SELECT 'supplementary_exams.grades.view' code,'View supplementary grades' name UNION ALL SELECT 'supplementary_exams.grades.assign','Assign supplementary grader' UNION ALL SELECT 'supplementary_exams.grades.enter','Enter supplementary theoretical grades' UNION ALL SELECT 'supplementary_exams.grades.review','Review supplementary grades' UNION ALL SELECT 'supplementary_exams.grades.publish','Publish supplementary grades') x JOIN `alrowad_uni_rust`.`system_modules` m ON m.module_code='exams' WHERE @apply_ready AND NOT EXISTS(SELECT 1 FROM `alrowad_uni_rust`.`permissions` p WHERE p.permission_code=x.code);
INSERT INTO `alrowad_uni_rust`.`role_permissions` (`role_id`,`permission_id`,`granted_at`) SELECT r.role_id,p.permission_id,CURRENT_TIMESTAMP FROM `alrowad_uni_rust`.`roles` r JOIN `alrowad_uni_rust`.`permissions` p ON ((r.role_code='doctor_instructor' AND p.permission_code IN ('supplementary_exams.grades.view','supplementary_exams.grades.enter')) OR (r.role_code='exam_officer' AND p.permission_code IN ('supplementary_exams.grades.view','supplementary_exams.grades.assign','supplementary_exams.grades.enter','supplementary_exams.grades.review','supplementary_exams.grades.publish'))) WHERE @apply_ready AND p.description='owned:supplementary-exam-grading-phase5' AND NOT EXISTS(SELECT 1 FROM `alrowad_uni_rust`.`role_permissions` rp WHERE rp.role_id=r.role_id AND rp.permission_id=p.permission_id);
COMMIT;
SET @permission_conflicts := (SELECT COUNT(*) FROM `alrowad_uni_rust`.`permissions` p LEFT JOIN `alrowad_uni_rust`.`system_modules` m ON m.module_id=p.module_id WHERE p.permission_code IN ('supplementary_exams.grades.view','supplementary_exams.grades.assign','supplementary_exams.grades.enter','supplementary_exams.grades.review','supplementary_exams.grades.publish') AND (p.is_active<>1 OR m.module_code<>'exams'));
SET @forbidden_mappings := (SELECT COUNT(*) FROM `alrowad_uni_rust`.`role_permissions` rp JOIN `alrowad_uni_rust`.`roles` r ON r.role_id=rp.role_id JOIN `alrowad_uni_rust`.`permissions` p ON p.permission_id=rp.permission_id WHERE p.permission_code IN ('supplementary_exams.grades.view','supplementary_exams.grades.assign','supplementary_exams.grades.enter','supplementary_exams.grades.review','supplementary_exams.grades.publish') AND NOT ((r.role_code='doctor_instructor' AND p.permission_code IN ('supplementary_exams.grades.view','supplementary_exams.grades.enter')) OR (r.role_code='exam_officer' AND p.permission_code IN ('supplementary_exams.grades.view','supplementary_exams.grades.assign','supplementary_exams.grades.enter','supplementary_exams.grades.review','supplementary_exams.grades.publish'))));
SET @rbac_adoption_conflicts := (SELECT COUNT(*) FROM `alrowad_uni_rust`.`permissions` p WHERE p.permission_code IN ('supplementary_exams.grades.view','supplementary_exams.grades.assign','supplementary_exams.grades.enter','supplementary_exams.grades.review','supplementary_exams.grades.publish') AND COALESCE(p.description,'')<>'owned:supplementary-exam-grading-phase5' AND NOT EXISTS (SELECT 1 FROM `alrowad_uni_rust`.`role_permissions` rp JOIN `alrowad_uni_rust`.`roles` r ON r.role_id=rp.role_id WHERE rp.permission_id=p.permission_id AND ((r.role_code='doctor_instructor' AND p.permission_code IN ('supplementary_exams.grades.view','supplementary_exams.grades.enter')) OR (r.role_code='exam_officer' AND p.permission_code IN ('supplementary_exams.grades.view','supplementary_exams.grades.assign','supplementary_exams.grades.enter','supplementary_exams.grades.review','supplementary_exams.grades.publish')))));
SET @rbac_safe := @permission_conflicts=0 AND @forbidden_mappings=0 AND @rbac_adoption_conflicts=0;
SET @expected_mappings := (SELECT COUNT(DISTINCT CONCAT(r.role_code,':',p.permission_code))=7 FROM `alrowad_uni_rust`.`role_permissions` rp JOIN `alrowad_uni_rust`.`roles` r ON r.role_id=rp.role_id JOIN `alrowad_uni_rust`.`permissions` p ON p.permission_id=rp.permission_id WHERE (r.role_code='doctor_instructor' AND p.permission_code IN ('supplementary_exams.grades.view','supplementary_exams.grades.enter')) OR (r.role_code='exam_officer' AND p.permission_code IN ('supplementary_exams.grades.view','supplementary_exams.grades.assign','supplementary_exams.grades.enter','supplementary_exams.grades.review','supplementary_exams.grades.publish')));
SET @permissions_ready := (SELECT COUNT(*)=5 FROM `alrowad_uni_rust`.`permissions` p JOIN `alrowad_uni_rust`.`system_modules` m ON m.module_id=p.module_id WHERE p.permission_code IN ('supplementary_exams.grades.view','supplementary_exams.grades.assign','supplementary_exams.grades.enter','supplementary_exams.grades.review','supplementary_exams.grades.publish') AND p.is_active=1 AND m.module_code='exams');
SET @apply_success := @apply_ready AND @permissions_ready AND @expected_mappings AND @forbidden_mappings=0;
SET @after_owned_permissions := (SELECT COUNT(*) FROM `alrowad_uni_rust`.`permissions` WHERE description='owned:supplementary-exam-grading-phase5' AND permission_code IN ('supplementary_exams.grades.view','supplementary_exams.grades.assign','supplementary_exams.grades.enter','supplementary_exams.grades.review','supplementary_exams.grades.publish'));
-- This is the only visible operator report and must remain the final statement.
SELECT 'OVERALL' AS report_section, IF(NOT @apply_success,'BLOCKED',IF(@initial_absent=0 AND @after_owned_permissions=@before_owned_permissions,'ALREADY_APPLIED','APPLIED')) AS result;
